// Generated by Suite Builder from a crawl of the site. The suite's menu: crew, help, suite or ask, typed in its folder.
// EDIT RULES: do not edit this file; regenerating replaces all of it. The menu is menu/menu.mjs; your own commands go in a file of your own.
// The suite's own menu (G-212): the word a person reaches for in this folder (crew, help, suite or ask)
// opens it. Where the suite stands (its last run, its stories, the site's problems), then what to do:
// Claude Code on the failures or the new stories, a run of the tests, the audit. Each choice says what it
// does; once done, the command it was, to type next time. It starts only the suite's own tests, Claude
// Code with the person, and the computer's own viewer for the audit: never Suite Builder (G-167).
import { spawnSync } from 'node:child_process';
import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { bold, choose, cyan, dim, tty } from './keys.mjs';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SITE = "playwright-playground.com";
const FRAMEWORK = "Playwright";
/** The suite's own test runs, as typed: the quick check, every test; what installs their packages first, if any. */
const QUICK = ["mvn","test","-Dgroups=smoke"];
const ALL = ["mvn","test"];
const INSTALL = null;
const REPORT = "target/report.html";
/** The run's pack: its failures, screenshots and reports zipped, to send to whoever helps (G-213). */
const PACK = ["java","pack/Pack.java","--run"];
const WIN = process.platform === 'win32';
const word = process.argv[2] || 'crew';

// Typed with more after it: "suite build ..." here is Suite Builder's, which a suite never starts (G-167).
if (word === 'suite' && process.argv.length > 3) {
  console.log(`You are inside a suite, so "suite" here opens its own menu (type ${cyan('suite')} alone).`);
  console.log(`Suite Builder's commands run from any other folder: ${cyan(`cd .. then suite ${process.argv.slice(3).join(' ')}`)}`);
  process.exit(1);
}

const plural = (n, one, many = `${one}s`) => `${n} ${n === 1 ? one : many}`;
const files = (dir) => (existsSync(join(ROOT, dir)) ? readdirSync(join(ROOT, dir)).filter((f) => f !== 'README.md' && !f.startsWith('.')) : []);

/** The last run, from the report page every run writes: passed, failed, when. */
function lastRun() {
  const page = join(ROOT, REPORT);
  if (!existsSync(page)) return null;
  const html = readFileSync(page, 'utf8');
  const count = (state) => html.split(`<tr class=${state}>`).length - 1;
  return { when: statSync(page).mtime, passed: count('passed'), failed: count('failed') };
}

/** A story waits on its person when its last push-back or proposed rewrite has no answer under it. */
function waits(text) {
  const at = Math.max(text.lastIndexOf('---- PUSHBACK'), text.lastIndexOf('---- PROPOSED REWRITE'));
  return at >= 0 && !/^Answer:/m.test(text.slice(at));
}

function state() {
  const stories = files('stories/new').map((f) => readFileSync(join(ROOT, 'stories', 'new', f), 'utf8'));
  const issues = existsSync(join(ROOT, 'KNOWN-ISSUES.md')) ? readFileSync(join(ROOT, 'KNOWN-ISSUES.md'), 'utf8') : '';
  return {
    run: lastRun(),
    fresh: stories.filter((t) => !waits(t)).length,
    waiting: stories.filter(waits).length,
    done: files('stories/done').length,
    problems: (issues.match(/^### (MAJOR|MINOR|INFO) SITE-/gm) ?? []).length,
    major: (issues.match(/^### MAJOR SITE-/gm) ?? []).length,
    jira: jiraState(),
  };
}

/** The Jira loop on this computer (G-214): connected or not, the project, and how many outcomes wait to be sent. */
function jiraState() {
  const settings = join(ROOT, 'jira-loop', 'jira.properties');
  if (!existsSync(settings)) return null;
  const value = (name) => new RegExp(`^\\s*${name}\\s*=\\s*(.*?)\\s*$`, 'm').exec(readFileSync(settings, 'utf8'))?.[1] ?? '';
  const account = join(ROOT, 'secrets', 'jira.login');
  const token = Boolean(process.env.JIRA_API_TOKEN) || (existsSync(account) && /^Password:\s*\S/m.test(readFileSync(account, 'utf8')));
  if (!value('site') || !token) return { connected: false };
  const pending = spawnSync(process.execPath, [join(ROOT, 'jira-loop', 'sync.mjs'), 'pending'], { cwd: ROOT, encoding: 'utf8' });
  return { connected: true, project: value('project'), toSend: pending.status === 0 ? JSON.parse(pending.stdout).length : 0 };
}

function when(d) {
  const days = Math.round((new Date().setHours(0, 0, 0, 0) - new Date(d).setHours(0, 0, 0, 0)) / 86_400_000);
  const time = `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
  return days <= 0 ? `today ${time}` : days === 1 ? `yesterday ${time}` : days < 7 ? `${days} days ago` : d.toISOString().slice(0, 10);
}

function header(s) {
  const tests = !s.run ? 'not run here yet' : `${s.run.failed ? `${plural(s.run.failed, 'test')} failed, ` : 'all passed, '}${s.run.passed} passed (last run ${when(s.run.when)})`;
  const stories = [s.waiting && `${s.waiting} waiting on you`, s.fresh && `${s.fresh} new`, `${s.done} done`].filter(Boolean).join(' · ');
  const site = s.problems ? `${plural(s.problems, 'problem')} found${s.major ? ` (${s.major} major)` : ''}` : 'nothing wrong found';
  const jira = !s.jira ? [] : [`  ${'Jira'.padEnd(10)}${s.jira.connected ? `connected, project ${s.jira.project}${s.jira.toSend ? ` · ${plural(s.jira.toSend, 'result')} to send` : ''}` : 'not connected (jira login)'}`];
  return ['', `  ${bold(`${SITE}: ${FRAMEWORK} test suite`)}`, `  ${'Tests'.padEnd(10)}${tests}`, `  ${'Stories'.padEnd(10)}${stories}`, `  ${'The site'.padEnd(10)}${site}`, ...jira, ''];
}

/** What to do, the most useful first. */
function choices(s) {
  const claude = (label, what, args) => ({ label, what, typed: `claude${args.length ? ` "${args[0]}"` : ''}`, run: () => openClaude(args) });
  const test = (label, what, cmd) => ({ label, what, typed: cmd.join(' '), run: () => runTests(cmd) });
  const jira = (label, what, args) => ({ label, what, typed: `jira ${args.join(' ')}`, run: () => spawnSync(process.execPath, [join(ROOT, 'jira-loop', 'jira.mjs'), ...args], { cwd: ROOT, stdio: 'inherit' }).status ?? 1 });
  const connected = s.jira?.connected;
  const quick = test('Run the quick check', 'Opens every kind of page once, in a browser, and says which fail. Changes nothing but its report.', QUICK);
  return [
    ...(!s.run ? [quick] : []),
    ...(s.run?.failed ? [claude(`Ask Claude why ${plural(s.run.failed, 'test')} failed`, 'Claude Code reads the failures\' evidence, fixes what is the suite\'s fault, and lists what is the site\'s. You see each change.', ['/fix-failing'])] : []),
    ...(connected && s.jira.toSend ? [jira(`Send ${plural(s.jira.toSend, 'result')} to Jira`, 'Shows what each card will get (its comment, where it moves), then sends when you say so. The BA sees it.', ['push'])] : []),
    ...(connected ? [jira('Get the stories ready in Jira', 'Brings the stories waiting in the watched statuses into stories/new/. Changes nothing in Jira.', ['pull'])] : []),
    ...(s.fresh ? [claude(`Turn ${plural(s.fresh, 'new story', 'new stories')} into tests`, 'Claude Code writes a test for each, or says exactly what it needs from you. You see each change.', ['/stories'])] : []),
    ...(s.run ? [quick] : []),
    ...(s.run ? [test('Pack this run to send', 'Zips this run\'s failures (each one\'s screenshot and why it failed), its report and the crawl, without the bulky traces, beside this folder: to send to whoever helps. Says its size.', PACK)] : []),
    test('Run every test', 'Every test, in a browser: a few minutes. Its report: ' + REPORT, ALL),
    ...(existsSync(join(ROOT, 'AUDIT.html')) ? [
      { label: 'Open the site\'s audit', what: 'What is wrong with the site, the most serious first, with why it matters and the fix: opened in your browser.', typed: 'open AUDIT.html (a double-click opens it)', run: openAudit },
      claude('Have Claude explain the audit', 'In plain words, for the site\'s owner: the most serious first, and the three to fix first. Changes no file.', ['/explain-audit']),
    ] : []),
    ...(s.jira && !connected ? [jira('Connect to Jira', 'Your Jira\'s address and a token, then the project and its statuses, chosen from lists. Asked once; jira-loop/README.md says the rest.', ['login'])] : []),
    { label: 'Open the test library', what: 'Every family and every test on one page in your browser, each with its last result: click one to run it, and watch it go. Only on this computer.', typed: 'node menu/library.mjs', run: () => spawnSync(process.execPath, [join(ROOT, 'menu', 'library.mjs')], { cwd: ROOT, stdio: 'inherit' }).status ?? 0 },
    claude('Ask Claude anything about this suite', 'Opens Claude Code here: say what you want in your own words.', []),
    { label: 'Every command, to type yourself', what: 'The commands behind each choice, to read: nothing runs.', typed: `${word} (this menu)`, run: listCommands },
  ];
}

/** The suite's tests, run as typed: its packages installed first when they are not. */
function runTests(cmd) {
  if (INSTALL && !existsSync(join(ROOT, 'node_modules'))) {
    console.log(`First, once: ${cyan(INSTALL.join(' '))} (it downloads what the tests need: minutes, silently)`);
    if (start(INSTALL) !== 0) return 1;
  }
  return start(cmd);
}

function start(cmd) {
  const run = spawnSync(cmd[0], cmd.slice(1), { cwd: ROOT, stdio: 'inherit', shell: WIN });
  if (run.error) {
    console.log(`Could not run ${cmd[0]}: is it installed? (README.md, "Run it", says what the suite needs.)`);
    return 1;
  }
  return run.status ?? 0;
}

/** Claude Code, in this folder, with the person: signed in to their own account. Not installed: how to install it. */
function openClaude(args) {
  const run = spawnSync('claude', args, { cwd: ROOT, stdio: 'inherit', shell: WIN });
  if (!run.error && run.status !== 9009 && run.status !== 127) return run.status ?? 0;
  console.log(`Claude Code is not installed here. Install it once (${cyan('npm install -g @anthropic-ai/claude-code')}), sign in with your own account, and choose this again.`);
  return 1;
}

/** The audit, opened by the computer's own viewer for a page. */
function openAudit() {
  const file = join(ROOT, 'AUDIT.html');
  // Windows' explorer opens a page in the default browser (and answers 1 even then).
  const viewer = WIN ? ['explorer', file] : process.platform === 'darwin' ? ['open', file] : ['xdg-open', file];
  const run = spawnSync(viewer[0], viewer.slice(1), { stdio: 'ignore' });
  console.log(run.error || (!WIN && run.status) ? `Open it in a browser: ${file}` : 'Opened in your browser.');
  return 0;
}

function listCommands() {
  console.log(`${bold('In this folder')}
  ${cyan(QUICK.join(' ').padEnd(34))}the quick check: every kind of page opens
  ${cyan(ALL.join(' ').padEnd(34))}every test
  ${cyan(PACK.join(' ').padEnd(34))}this run, zipped to send (add --trace <test> for one replay)
  ${cyan('claude'.padEnd(34))}Claude Code, then /stories, /fix-failing or /explain-audit
  ${cyan('jira'.padEnd(34))}Jira: login, pull, push, status, watch, output (jira-loop/README.md)
  ${cyan(word.padEnd(34))}this menu (crew, help, suite and ask all open it)
Everything else: README.md.`);
  return 0;
}

const s = state();
const list = choices(s);
console.log(header(s).join('\n'));
if (!tty) {
  // Not a person at a terminal (a script, a log): the choices and their commands, as help.
  for (const c of list) console.log(`  ${c.label.padEnd(40)}${c.typed}`);
  process.exit(0);
}
console.log('  What would you like to do?\n');
const picked = await choose(list);
if (picked === null) process.exit(0);
console.log('');
const code = await list[picked].run();
if (list[picked].typed && !list[picked].typed.startsWith(word)) console.log(`\n${dim('Next time, type:')} ${cyan(list[picked].typed)}`);
process.exit(code);
